//! Type-safe bitflag sets that can be freely combined and checked.
//!
//! Flag sets are newtypes generated by [`bitflags`], so they cannot be
//! accidentally mixed with a plain integer or with a different flag type.
//! Combinations are built with `|`, `&`, `^` and `!`, and inspected with
//! [`contains`](Permissions::contains) / [`intersects`](Permissions::intersects)
//! or the domain helpers on [`Permissions`].
//!
//! ```
//! use typed_flags::Permissions;
//!
//! let perms = Permissions::READ | Permissions::WRITE;
//!
//! assert!(perms.contains(Permissions::READ));
//! assert!(perms.intersects(Permissions::WRITE));
//! assert!(!perms.contains(Permissions::EXECUTE));
//! ```

use bitflags::bitflags;

bitflags! {
    /// A set of filesystem access rights.
    ///
    /// Rights are combined with the bitwise operators and queried with the
    /// methods provided by `bitflags` plus the `has_*` helpers below.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct Permissions: u32 {
        /// Permission to read a resource.
        const READ    = 0b0000_0001;
        /// Permission to modify a resource.
        const WRITE   = 0b0000_0010;
        /// Permission to run a resource.
        const EXECUTE = 0b0000_0100;

        /// Read, write and execute.
        const ALL = Self::READ.bits()
            | Self::WRITE.bits()
            | Self::EXECUTE.bits();
    }
}

impl Permissions {
    /// An empty set, granting no access.
    pub const NONE: Self = Self::empty();

    /// Returns `true` if every flag in `other` is present in `self`.
    #[inline]
    pub const fn has_all(self, other: Self) -> bool {
        self.contains(other)
    }

    /// Returns `true` if at least one flag in `other` is present in `self`.
    #[inline]
    pub const fn has_any(self, other: Self) -> bool {
        self.intersects(other)
    }

    /// Returns a copy of `self` with the flags in `other` added.
    #[inline]
    pub const fn with(self, other: Self) -> Self {
        Self::from_bits_retain(self.bits() | other.bits())
    }

    /// Returns a copy of `self` with the flags in `other` removed.
    #[inline]
    pub const fn without(self, other: Self) -> Self {
        Self::from_bits_retain(self.bits() & !other.bits())
    }

    /// Returns a copy of `self` with the flags in `other` toggled.
    #[inline]
    pub const fn toggled(self, other: Self) -> Self {
        Self::from_bits_retain(self.bits() ^ other.bits())
    }

    /// The number of individual flags that are set.
    #[inline]
    pub const fn flag_count(self) -> u32 {
        self.bits().count_ones()
    }
}

#[cfg(test)]
mod tests {
    use super::Permissions;

    #[test]
    fn combines_with_bitwise_or() {
        let perms = Permissions::READ | Permissions::WRITE;
        assert_eq!(perms, Permissions::READ.with(Permissions::WRITE));
        assert_eq!(perms.flag_count(), 2);
    }

    #[test]
    fn checks_membership() {
        let perms = Permissions::READ | Permissions::WRITE;
        assert!(perms.contains(Permissions::READ));
        assert!(perms.has_any(Permissions::WRITE | Permissions::EXECUTE));
        assert!(!perms.has_all(Permissions::ALL));
        assert!((Permissions::ALL).has_all(Permissions::READ | Permissions::WRITE));
    }

    #[test]
    fn adds_removes_and_toggles_flags() {
        let mut perms = Permissions::empty();
        perms.insert(Permissions::READ);
        perms.insert(Permissions::WRITE);
        assert_eq!(perms, Permissions::READ | Permissions::WRITE);

        perms.remove(Permissions::READ);
        assert_eq!(perms, Permissions::WRITE);

        perms.toggle(Permissions::EXECUTE);
        assert_eq!(perms, Permissions::WRITE | Permissions::EXECUTE);
    }

    #[test]
    fn empty_and_full_sets() {
        assert!(Permissions::empty().is_empty());
        assert!(Permissions::NONE.is_empty());
        assert!(Permissions::all() == Permissions::ALL);
        assert!(!Permissions::READ.is_empty());
        assert!(Permissions::ALL
            .without(Permissions::EXECUTE)
            .contains(Permissions::READ));
    }

    #[test]
    fn rejects_unknown_bits() {
        assert_eq!(
            Permissions::from_bits(0b1000),
            None,
            "bit 3 is not a declared flag"
        );
        assert_eq!(
            Permissions::from_bits(0b101),
            Some(Permissions::READ | Permissions::EXECUTE)
        );
    }

    #[test]
    fn converts_to_and_from_raw_bits() {
        let perms = Permissions::from_bits_retain(0b11);
        assert_eq!(perms, Permissions::READ | Permissions::WRITE);
        let raw: u32 = perms.bits();
        assert_eq!(raw, 0b11);
    }

    #[test]
    fn toggles_flags_without_mutating() {
        let perms = Permissions::READ | Permissions::EXECUTE;
        assert_eq!(perms.toggled(Permissions::EXECUTE), Permissions::READ);
    }
}
